DROP TABLE IF EXISTS `data_mobinfo`;
CREATE TABLE `data_mobinfo` (
  `ID` SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  `InxName` VARCHAR(32) NOT NULL DEFAULT '',
  `Name` VARCHAR(32) NOT NULL DEFAULT '',
  `Level` INT UNSIGNED NOT NULL DEFAULT 0,
  `MaxHP` INT UNSIGNED NOT NULL DEFAULT 0,
  `WalkSpeed` INT UNSIGNED NOT NULL DEFAULT 0,
  `RunSpeed` INT UNSIGNED NOT NULL DEFAULT 0,
  `IsNPC` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `Size` INT UNSIGNED NOT NULL DEFAULT 0,
  `WeaponType` INT UNSIGNED NOT NULL DEFAULT 0,
  `ArmorType` INT UNSIGNED NOT NULL DEFAULT 0,
  `GradeType` INT UNSIGNED NOT NULL DEFAULT 0,
  `Type` INT UNSIGNED NOT NULL DEFAULT 0,
  `IsPlayerSide` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `AbsoluteSize` INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

